import logging
import queue
import threading

logger = logging.getLogger(__name__)

_SHUTDOWN = object()


class QueueWorker:
    """Runs a callback against each item pulled from a queue on a worker thread."""

    def __init__(self, handle_item, work_queue=None, name="queue-worker"):
        self.handle_item = handle_item
        self.queue = work_queue if work_queue is not None else queue.Queue()
        self.thread = threading.Thread(target=self._drain, name=name, daemon=True)
        self.started = False

    def start(self):
        if self.started:
            raise RuntimeError("worker already started")
        self.started = True
        self.thread.start()

    def submit(self, item):
        self.queue.put(item)

    def _drain(self):
        while True:
            item = self.queue.get()
            try:
                if item is _SHUTDOWN:
                    return
                self.handle_item(item)
            except Exception:
                logger.exception("handler failed for %r", item)
            finally:
                self.queue.task_done()

    def join_pending(self):
        """Block until every item submitted so far has been handled."""
        self.queue.join()

    def stop(self, timeout=None):
        """Finish the queued backlog, then shut the thread down."""
        if not self.started:
            return
        self.queue.put(_SHUTDOWN)
        self.thread.join(timeout)
        if self.thread.is_alive():
            logger.warning("worker %s did not exit within %ss", self.thread.name, timeout)
        self.started = False

    def __enter__(self):
        self.start()
        return self

    def __exit__(self, exc_type, exc, tb):
        self.stop()
        return False
